------------ import ------------
local KTool = CS.Engine.Lib.KTool
local GroceryUtils = import('Game.Grocery.GroceryUtils')
local ActivityPtUtils = import('Game.UI.FightReady.UIActivityPt.ActivityPtUtils')

------------ import ------------
local TagType = {
    Discount = 1, -- 折扣标签
    Activity = 2, -- 活动标签
}
                       
--- from: Assets/BundleResources/Prefabs/OverseaStore/OverseaStoreItemCell.prefab
---@class UIActivityPtShopCellNode
---@field Env                           	UIActivityPtShopCellNode                
---@field controller                    	Engine.Modules.LuaBehaviour             
local UIActivityPtShopCellNode = Class('UIActivityPtShopCellNode')

function UIActivityPtShopCellNode:__init()
    self._data = nil
end

function UIActivityPtShopCellNode:__delete()
    self._data = nil
end

function UIActivityPtShopCellNode:Awake()
    SetButtonAction(self.BtnNode, Bind(self, self.OnClick))
end

function UIActivityPtShopCellNode:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb

    self:FillSelf()
end

function UIActivityPtShopCellNode:RefreshData(data)
    if not data then
        return
    end
    self._data = data
    self:FillSelf()
end

function UIActivityPtShopCellNode:FillSelf()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.icon)
    if not vo then return end

    -- icon
    CfUtils.FillImage(self.ImgIcon, vo.photoPath)
    -- 品质
    CfUtils.FillImage(self.GoodQuality, GroceryUtils.GetGoodsBgByQuality(vo.quality))
    CfUtils.FillImage(self.GoodQuality2, GroceryUtils.GetGoodsBgByQuality(vo.quality))
    CfUtils.SetActive(self.BtnNode.transform:Find("TimerGroup"), false)

    -- name
    CfUtils.FillText(self.TextName, vo.name .. "x" ..self._data.num)

    -- 库存
    if checkNumber(self._data.stock) == -1 then
        CfUtils.SetActive(self.Stock, false)
    else
        CfUtils.SetActive(self.Stock, true)
        CfUtils.FillText(self.TextNumber, self._data.currentStock)
    end

    local keys = table.keys(self._data.prices)
    CfUtils.SetActive(self.ImgIcon2, true)
    CfUtils.FillImage(self.ImgIcon2, GoodsConfMgr:GetInstance():GetPhotoPathById(keys[1]))
    CfUtils.FillText(self.TextNumber3, self._data.prices[keys[1]].current)
    CfUtils.SetActive(self.PriceObject.transform:Find("Price1/Price2"), false)

    -- 标签
    local tabType = checkInt(self._data.iconId)
    if tabType == TagType.Activity then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
        local type = checkInt(self._data.iconTitle)
        CfUtils.SetUISwitchImage(self.ActivityImgBg, type)
        CfUtils.SetUISwitchImage(self.ActivityImgTabel, type)
        CfUtils.SetUISwitchText(self.ActivityText, type)
    elseif tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, self._data.iconTitle)
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
    end
    
    --特殊类型处理
    local goodsType = GoodsUtils.GetIdType(self._data.icon)
    if goodsType == Constants.IDType.Equipment then
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetActive(self.RoleGoods, false)
    elseif goodsType == Constants.IDType.CardSkin or goodsType == Constants.IDType.CharacterCard then
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.RoleGoods, true)
        CfUtils.SetActive(self.ImgOccupation, goodsType == Constants.IDType.CardSkin)
        CfUtils.FillImage(self.ImgRoleIcon, vo.photoPath)
    else
        CfUtils.SetActive(self.EquipGroup, false)
        CfUtils.SetActive(self.RoleGoods, false)
        CfUtils.SetActive(self.ImgIcon, true)
    end

    local isLocked = not ActivityPtUtils.IsPassQuest(self._data.unlockStory)  --GroceryUtils.ProductIsLocked(self._data)
    local isSoldOut = GroceryUtils.ProductIsSoldOut(self._data)
    CfUtils.SetActive(self.DisableBg, isSoldOut or isLocked)
    CfUtils.SetActive(self.LockGroup, isLocked)
    CfUtils.SetActive(self.SellOutGroup, isSoldOut)

    CfUtils.SetActive(self.Text2, isLocked)
    if isLocked then
        local vo = ActivityPtUtils.GetActivityPtPlotVo(self._data.unlockStory)
        CfUtils.FillText(self.Text2, vo.name)
    else
    end
end

function UIActivityPtShopCellNode:OnClick()
    local isLocked, lockedDesc = not ActivityPtUtils.IsPassQuest(self._data.unlockStory)  --GroceryUtils.ProductIsLocked(self._data)
    if isLocked then
        local vo = ActivityPtUtils.GetActivityPtPlotVo(self._data.unlockStory)
        GameUtils.Toast(localize("完成活动故事_name_后解锁", {_name_ = vo.name}))
        return
    end
    if not self._cb then
        return
    end
    self._cb()
end

function UIActivityPtShopCellNode:PlanyAniByName(name)
end

function UIActivityPtShopCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityPtShopCellNode
